  await Promise.all(ch.map((l,i)=>wait(i*90).then(()=>{l.style.opacity=1;l.style.left=(CL(2)+48+i*11)+'px';tone(400+i*60,.1,'triangle',.12,500+i*60)})));
  await wait(500);c.remove();R['av2'].innerHTML=H.nm('🧔');R['av2'].style.transform='';
  const m1=K('💍','MARIÉ',CL(3)+20,60,''),m2=K('💍','MARIÉ',CL(2)+20,60,'');
  bigFx('💞',150,60,'#fff','ok');
  const p1=pill('😊 +3',CL(3)+22,114),p2=pill('😊 +3',CL(2)+22,114);
