  [[0,-17,0,-5],[0,5,0,17],[-17,0,-5,0],[5,0,17,0]].forEach(l=>mk('line',{x1:l[0],y1:l[1],x2:l[2],y2:l[3],stroke:'#ff4a3c','stroke-width':2},X));
